-- ch11_pronouns.sql
-- Latina Exercitia: Wheelock Capvt XI pronoun paradigms for the Demonstratives tab.
--   ego, tu: new group 'Personal pronouns' (single-column, is_noun = true).
--   is, idem: join the existing 'Demonstratives' group.
-- Alternative answers are written a|b (e.g. nostrum|nostri); needs the matching index.html (deploy that first).
-- 4 rows. Insert file: run ONCE. A second run fails with "duplicate key" (unique index drills_one_item_per_file).
-- Reversible: delete from drills where session_tag = 'wheelock_ch11_pronouns';

insert into drills (type, lp_multiplier, session_tag, content) values
('demonstrative', 1.2, 'wheelock_ch11_pronouns', '{"lemma": "ego", "chapter": 11, "group": "Personal pronouns", "display": "ego, mei", "is_noun": true, "meaning": "I, me; plural nos, we, us", "note": "No gender: one form per case. Two genitive plurals, nostrum and nostri (either is accepted). These genitives are not used for possession: \"my\" and \"our\" are the adjectives meus and noster. With cum the preposition is attached to the end: mecum, nobiscum.", "paradigm": {"s": {"Nominative": "ego", "Genitive": "mei", "Dative": "mihi", "Accusative": "me", "Ablative": "me"}, "p": {"Nominative": "nos", "Genitive": "nostrum|nostri", "Dative": "nobis", "Accusative": "nos", "Ablative": "nobis"}}}'::jsonb),
('demonstrative', 1.2, 'wheelock_ch11_pronouns', '{"lemma": "tu", "chapter": 11, "group": "Personal pronouns", "display": "tu, tui", "is_noun": true, "meaning": "you (singular); plural vos, you (all)", "note": "Declines like ego. Two genitive plurals, vestrum and vestri (either is accepted); not used for possession, which takes tuus and vester. With cum: tecum, vobiscum.", "paradigm": {"s": {"Nominative": "tu", "Genitive": "tui", "Dative": "tibi", "Accusative": "te", "Ablative": "te"}, "p": {"Nominative": "vos", "Genitive": "vestrum|vestri", "Dative": "vobis", "Accusative": "vos", "Ablative": "vobis"}}}'::jsonb),
('demonstrative', 1.2, 'wheelock_ch11_pronouns', '{"lemma": "is", "chapter": 11, "group": "Demonstratives", "display": "is / ea / id", "is_noun": false, "meaning": "he, she, it; this, that", "note": "Endings mostly follow magnus on the stem e-, except nom. is / id, gen. sg. eius and dat. sg. ei in all genders. Masc. nom. pl. ei or ii (either is accepted). Its genitives eius, eorum, earum are the usual way to say his, her, its, their, and they do not change to agree with the thing owned.", "paradigm": {"s": {"Nominative": ["is", "ea", "id"], "Genitive": ["eius", "eius", "eius"], "Dative": ["ei", "ei", "ei"], "Accusative": ["eum", "eam", "id"], "Ablative": ["eo", "ea", "eo"]}, "p": {"Nominative": ["ei|ii", "eae", "ea"], "Genitive": ["eorum", "earum", "eorum"], "Dative": ["eis", "eis", "eis"], "Accusative": ["eos", "eas", "ea"], "Ablative": ["eis", "eis", "eis"]}}}'::jsonb),
('demonstrative', 1.2, 'wheelock_ch11_pronouns', '{"lemma": "idem", "chapter": 11, "group": "Demonstratives", "display": "idem / eadem / idem", "is_noun": false, "meaning": "the same", "note": "Forms of is with -dem added (eiusdem, eidem). Nominatives idem (masc., for *isdem) and idem (neut., for *iddem). Before -dem a final -m becomes -n: eundem, eandem, eorundem, earundem. Alternative plural forms iidem / idem and iisdem / isdem are accepted.", "paradigm": {"s": {"Nominative": ["idem", "eadem", "idem"], "Genitive": ["eiusdem", "eiusdem", "eiusdem"], "Dative": ["eidem", "eidem", "eidem"], "Accusative": ["eundem", "eandem", "idem"], "Ablative": ["eodem", "eadem", "eodem"]}, "p": {"Nominative": ["eidem|iidem|idem", "eaedem", "eadem"], "Genitive": ["eorundem", "earundem", "eorundem"], "Dative": ["eisdem|iisdem|isdem", "eisdem|iisdem|isdem", "eisdem|iisdem|isdem"], "Accusative": ["eosdem", "easdem", "eadem"], "Ablative": ["eisdem|iisdem|isdem", "eisdem|iisdem|isdem", "eisdem|iisdem|isdem"]}}}'::jsonb);
